    private void beginAlarmSave(JSONObject alarm,boolean edit,Dialog editor){
        pendingAlarmSave=alarm;pendingAlarmEdit=edit;pendingAlarmEditor=editor;
        long now=System.currentTimeMillis();int lead=Math.max(1,alarm.optInt("reminder_minutes",30));long alarmAt=DataStore.nextOccurrence(alarm,now);
        if(alarm.optBoolean("reminder_enabled",true)&&alarmAt-lead*60_000L<=now){
            String when=DataStore.formatDate(alarmAt)+" at "+DataStore.formatTime(this,alarm.optInt("hour",7),alarm.optInt("minute",0));
            alertBuilder().setTitle("No time for an early ping this time")
                    .setMessage("The next alarm at "+when+" is less than "+lead+" minutes away. TicTic cannot send a reminder in the past; the next repeating occurrence can still get one.")
                    .setNegativeButton("Review",(d,w)->clearPendingAlarmSave()).setPositiveButton("Continue",(d,w)->requestNotificationAccessInContext()).show();
        }else requestNotificationAccessInContext();
    }
    private void requestNotificationAccessInContext(){
        if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){
            alertBuilder().setTitle("Allow alarm notifications?")
                    .setMessage("Notifications deliver the pre-alarm ping and make ringing Snooze/Stop actions available on the lock screen. The active ringing notification never disables a repeating alarm; this access is optional, and Android may suppress notifications if it is denied.")
                    .setNegativeButton("Save without notifications",(d,w)->requestExactAccessBeforeSave())
                    .setNeutralButton("Cancel",(d,w)->clearPendingAlarmSave())
                    .setPositiveButton("Continue",(d,w)->requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},REQUEST_ALARM_NOTIFICATIONS)).show();
        }else requestExactAccessBeforeSave();
    }
    @Override public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] grantResults){
        super.onRequestPermissionsResult(requestCode,permissions,grantResults);
        if(requestCode==REQUEST_ALARM_NOTIFICATIONS){requestExactAccessBeforeSave();}
    }
    private void requestExactAccessBeforeSave(){
        if(Build.VERSION.SDK_INT>=31&&!AlarmScheduler.canExact(this)){
            alertBuilder().setTitle("Allow on-time alarms?")
                    .setMessage("“Alarms & reminders” is special app access needed for exact, on-time delivery. It is not required to save an alarm, but without it Android may delay the alarm and its early reminder; choose Set with possible delay to continue without it.")
                    .setNeutralButton("Cancel",(d,w)->clearPendingAlarmSave())
                    .setNegativeButton("Set with possible delay",(d,w)->checkFullScreenBeforeSave(false))
                    .setPositiveButton("Open Settings",(d,w)->{checkFullScreenBeforeSave(true);})
                    .show();
        }else checkFullScreenBeforeSave(false);
    }
    private void checkFullScreenBeforeSave(boolean openExactSettings){
        if(Build.VERSION.SDK_INT>=34&&!((android.app.NotificationManager)getSystemService(NOTIFICATION_SERVICE)).canUseFullScreenIntent()){
            alertBuilder().setTitle("Full-screen alarm view is off")
                    .setMessage("This optional special access lets Android show TicTic’s large ringing screen while the phone is locked. Snooze and Stop remain available in the notification. Alarms & reminders is a separate special access; you can manage it from Settings → Permissions & access.")
                    .setNegativeButton("Use notification only",(d,w)->{commitPendingAlarmSave();if(openExactSettings)openExactAlarmSettings();})
                    .setPositiveButton("Open full-screen settings",(d,w)->{commitPendingAlarmSave();exactSettingsAfterFullScreen=openExactSettings;openFullScreenSettings();})
                    .setOnCancelListener(d->{clearPendingAlarmSave();}).show();
        }else{commitPendingAlarmSave();if(openExactSettings)openExactAlarmSettings();}
    }
