    private void timerButtonHaptic(View view){if(DataStore.prefs(this).getBoolean("timer_button_haptics",true))view.performHapticFeedback(android.view.HapticFeedbackConstants.CLOCK_TICK);}
    private void stopwatchButtonHaptic(View view){if(DataStore.prefs(this).getBoolean("stopwatch_button_haptics",true))view.performHapticFeedback(android.view.HapticFeedbackConstants.CLOCK_TICK);}
    private void buildTimer(){sectionTitle("Timer",null);gap(18);LinearLayout c=vbox();c.setGravity(Gravity.CENTER);c.setPadding(dp(18),dp(20),dp(18),dp(20));c.setBackground(shape(surface,26));body.addView(c,lp(-1,-2));TextView kicker=label("TIME REMAINING",10,muted,true);kicker.setLetterSpacing(.16f);c.addView(kicker);timerLive=label(duration(remaining()),56,text,true);timerLive.setGravity(Gravity.CENTER);timerLive.setSingleLine(true);timerLive.setIncludeFontPadding(true);timerLive.setMinHeight(dp(90));timerLive.setPadding(0,dp(8),0,dp(8));timerLive.setTextSize(duration(remaining()).length()>=8?46:56);LinearLayout.LayoutParams tl=lp(-1,-2);tl.topMargin=dp(5);c.addView(timerLive,tl);TextView edit=label("Set a custom countdown",12,muted,false);edit.setGravity(Gravity.CENTER);c.addView(edit);timerLive.setOnClickListener(v->chooseTimerLength());edit.setOnClickListener(v->chooseTimerLength());LinearLayout buttons=hbox();LinearLayout.LayoutParams bp=lp(-1,48);bp.topMargin=dp(10);c.addView(buttons,bp);String[] presetLabels={"1m","5m","10m","25m","1h"};long[] presetMillis={60000L,300000L,600000L,1500000L,3600000L};long activeDuration=DataStore.prefs(this).getLong("timer_duration",DataStore.prefs(this).getLong("timer_default_duration",300000L));for(int i=0;i<presetMillis.length;i++){final long duration=presetMillis[i];boolean chosen=!timerRunning()&&activeDuration==duration;TextView quick=pillButton(presetLabels[i],chosen?accent:(DataStore.dark(this)?0xff2c3d39:0xffedf3f1),chosen?Color.WHITE:text);quick.setTextSize(11);LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(0,dp(42),1);if(buttons.getChildCount()>0)pp.leftMargin=dp(5);buttons.addView(quick,pp);quick.setOnClickListener(v->{timerButtonHaptic(v);if(!timerRunning()){DataStore.prefs(this).edit().putLong("timer_duration",duration).putLong("timer_remaining",duration).apply();render();}else updateLive();});}
        LinearLayout actions=hbox();actions.setGravity(Gravity.CENTER);LinearLayout.LayoutParams ap=lp(-1,56);ap.topMargin=dp(12);c.addView(actions,ap);TextView start=pillButton(timerRunning()?"Pause":"Start timer",accent,Color.WHITE);actions.addView(start,new LinearLayout.LayoutParams(0,dp(50),2));TextView reset=pillButton("Reset",DataStore.dark(this)?0xff293b37:0xffedf3f1,text);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(0,dp(50),1);rp.leftMargin=dp(10);actions.addView(reset,rp);start.setOnClickListener(v->{timerButtonHaptic(v);if(timerRunning()){pauseTimer();render();}else requestTimerStart();});reset.setOnClickListener(v->{timerButtonHaptic(v);long selected=DataStore.prefs(this).getLong("timer_duration",DataStore.prefs(this).getLong("timer_default_duration",300000L));cancelTimer();DataStore.prefs(this).edit().putLong("timer_duration",selected).putLong("timer_remaining",selected).apply();render();});}
    private boolean timerRunning(){return TimerReceiver.isRunning(this);}
    private long remaining(){return TimerReceiver.remaining(this);}
    private String duration(long ms){if(DataStore.prefs(this).getBoolean("timer_show_hundredths",false))return TimeMath.formatCountdownHundredths(ms);long s=Math.max(0,(ms+999)/1000),h=s/3600,m=(s%3600)/60,ss=s%60;return h>0?String.format(Locale.getDefault(),"%02d:%02d:%02d",h,m,ss):String.format(Locale.getDefault(),"%02d:%02d",m,ss);}
    private void startTimer(){long dur=remaining();if(dur<=0)dur=DataStore.prefs(this).getLong("timer_default_duration",300000L);TimerReceiver.start(this,dur);DataStore.log(this,"Timer","Timer started",duration(dur));}
    private void requestTimerStart(){if(Build.VERSION.SDK_INT>=31&&!AlarmScheduler.canExact(this)){alertBuilder().setTitle("Allow an on-time timer alert?").setMessage("Android may delay the timer completion notification without Alarms & reminders access. You can start with a possible delay or open Android settings.").setNeutralButton("Cancel",null).setNegativeButton("Start with possible delay",(d,w)->{startTimer();render();}).setPositiveButton("Open settings & start",(d,w)->{startTimer();render();openExactAlarmSettings();}).show();return;}startTimer();render();}
    private void pauseTimer(){long left=remaining();TimerReceiver.pause(this,left);DataStore.log(this,"Timer","Timer paused",duration(left)+" remaining");}
    private void cancelTimer(){long def=DataStore.prefs(this).getLong("timer_duration",DataStore.prefs(this).getLong("timer_default_duration",300000L));TimerReceiver.reset(this,def);}
    private void chooseTimerLength(){long total=Math.max(0,(remaining()+999)/1000);total=Math.min(total,99L*3600+59*60+59);NumberPicker hours=timerNumberPicker(99),minutes=timerNumberPicker(59),seconds=timerNumberPicker(59);hours.setValue((int)(total/3600));minutes.setValue((int)((total%3600)/60));seconds.setValue((int)(total%60));LinearLayout form=vbox();form.setPadding(dp(18),dp(4),dp(18),dp(4));TextView preview=label(formatCountdown(hours.getValue(),minutes.getValue(),seconds.getValue()),32,accent,true);preview.setGravity(Gravity.CENTER);preview.setBackground(shape(DataStore.dark(this)?0xff243832:0xffe3eee9,18));LinearLayout.LayoutParams previewP=lp(-1,68);previewP.bottomMargin=dp(8);form.addView(preview,previewP);LinearLayout fields=hbox();fields.setGravity(Gravity.CENTER);form.addView(fields,lp(-1,138));addTimerPicker(fields,"HOURS",hours);addTimerPicker(fields,"MIN",minutes);addTimerPicker(fields,"SEC",seconds);NumberPicker.OnValueChangeListener changed=(picker,oldValue,newValue)->preview.setText(formatCountdown(hours.getValue(),minutes.getValue(),seconds.getValue()));hours.setOnValueChangedListener(changed);minutes.setOnValueChangedListener(changed);seconds.setOnValueChangedListener(changed);TextView hint=label("Choose hours, minutes and seconds",11,muted,false);hint.setGravity(Gravity.CENTER);form.addView(hint,lp(-1,25));AlertDialog dialog=alertBuilder().setTitle("Custom countdown").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Set timer",null).create();dialog.setOnShowListener(d->{dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{long secondsTotal=hours.getValue()*3600L+minutes.getValue()*60L+seconds.getValue();if(secondsTotal<=0){hint.setText("Choose at least one second.");hint.setTextColor(0xffc95b54);return;}long ms=secondsTotal*1000L;if(timerRunning())pauseTimer();DataStore.prefs(this).edit().putLong("timer_duration",ms).putLong("timer_remaining",ms).apply();dialog.dismiss();render();});});dialog.show();DialogFit.fit(ui(), dialog);}
    private NumberPicker timerNumberPicker(int max){NumberPicker picker=newNumberPicker();picker.setMinValue(0);picker.setMaxValue(max);picker.setWrapSelectorWheel(false);picker.setFormatter(value->String.format(Locale.getDefault(),"%02d",value));styleNumberPicker(picker);return picker;}
    private void addTimerPicker(LinearLayout row,String title,NumberPicker picker){LinearLayout column=vbox();column.setGravity(Gravity.CENTER);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-1,1);cp.leftMargin=dp(3);cp.rightMargin=dp(3);row.addView(column,cp);TextView label=label(title,9,muted,true);label.setGravity(Gravity.CENTER);column.addView(label,lp(-1,20));column.addView(picker,new LinearLayout.LayoutParams(-1,dp(112)));}
    private String formatCountdown(int hours,int minutes,int seconds){return String.format(Locale.getDefault(),"%02d:%02d:%02d",hours,minutes,seconds);}
    private void buildStopwatch(){if(stopwatchScreen!=null)stopwatchScreen.onPause();stopwatchScreen=new StopwatchScreen(this);body.addView(stopwatchScreen.build(this),lp(-1,-2));stopwatchScreen.onResume();}
    private boolean swRunning(){return DataStore.prefs(this).getBoolean("sw_running",false);}
    private long swElapsed(){android.content.SharedPreferences prefs=DataStore.prefs(this);long saved=prefs.getLong("sw_elapsed",0);if(!swRunning())return saved;long nowElapsed=SystemClock.elapsedRealtime(),nowWall=System.currentTimeMillis();long startElapsed=prefs.getLong("sw_start_elapsed",0),startWall=prefs.getLong("sw_start_wall",prefs.getLong("sw_start",0));int startBoot=prefs.getInt("sw_boot_count",-1),currentBoot=TimerReceiver.bootCount(this);if(startElapsed<=0&&startWall>0){long migrated=TimeMath.stopwatchElapsed(saved,0,startWall,nowElapsed,nowWall,-1,currentBoot);prefs.edit().putLong("sw_elapsed",migrated).putLong("sw_start_elapsed",nowElapsed).putLong("sw_start_wall",nowWall).putLong("sw_start",nowWall).putInt("sw_boot_count",currentBoot).apply();return migrated;}return TimeMath.stopwatchElapsed(saved,startElapsed,startWall,nowElapsed,nowWall,startBoot,currentBoot);}
    private String durationHundred(long ms){return TimeMath.formatHundredths(ms);}private String stopwatchDisplay(long ms){if(DataStore.prefs(this).getBoolean("stopwatch_show_hundredths",true))return durationHundred(ms);long seconds=Math.max(0,ms/1000),minutes=seconds/60,ss=seconds%60,h=minutes/60,m=minutes%60;return h>0?String.format(Locale.getDefault(),"%02d:%02d:%02d",h,m,ss):String.format(Locale.getDefault(),"%02d:%02d",minutes,ss);}
    private void stopwatchStart(){long nowWall=System.currentTimeMillis(),nowElapsed=SystemClock.elapsedRealtime();int boot=TimerReceiver.bootCount(this);DataStore.prefs(this).edit().putBoolean("sw_running",true).putLong("sw_start",nowWall).putLong("sw_start_wall",nowWall).putLong("sw_start_elapsed",nowElapsed).putInt("sw_boot_count",boot).apply();DataStore.log(this,"Stopwatch","Stopwatch started","Timing began");}
    private void stopwatchPause(){long e=swElapsed();DataStore.prefs(this).edit().putBoolean("sw_running",false).putLong("sw_elapsed",e).putLong("sw_start",0).remove("sw_start_wall").remove("sw_start_elapsed").remove("sw_boot_count").apply();DataStore.log(this,"Stopwatch","Stopwatch paused",durationHundred(e));}
    private void addLap(){long e=swElapsed(),prev=DataStore.prefs(this).getLong("sw_last_lap",0);JSONArray a=DataStore.array(this,"laps");try{a.put(new JSONObject().put("n",a.length()+1).put("ms",e).put("split",e-prev));}catch(Exception ignored){}DataStore.putArray(this,"laps",a);DataStore.prefs(this).edit().putLong("sw_last_lap",e).apply();DataStore.log(this,"Stopwatch","Lap recorded","Lap "+a.length()+" · "+durationHundred(e));}
    private void resetStopwatch(){long e=swElapsed();DataStore.prefs(this).edit().putBoolean("sw_running",false).putLong("sw_elapsed",0).putLong("sw_start",0).putLong("sw_last_lap",0).remove("sw_start_wall").remove("sw_start_elapsed").remove("sw_boot_count").apply();DataStore.prefs(this).edit().remove("laps").apply();if(e>0)DataStore.log(this,"Stopwatch","Stopwatch reset",durationHundred(e));}
    private String activityRangeCaption(){if(activityRangeDays<=1)return "Today · "+new SimpleDateFormat("EEEE · d MMM",Locale.getDefault()).format(new Date());Calendar end=Calendar.getInstance(),start=(Calendar)end.clone();start.add(Calendar.DAY_OF_YEAR,-(activityRangeDays-1));SimpleDateFormat f=new SimpleDateFormat("d MMM",Locale.getDefault());return f.format(start.getTime())+" — "+f.format(end.getTime());}
    private long activityRangeStartMillis(){Calendar start=Calendar.getInstance();start.set(Calendar.HOUR_OF_DAY,0);start.set(Calendar.MINUTE,0);start.set(Calendar.SECOND,0);start.set(Calendar.MILLISECOND,0);start.add(Calendar.DAY_OF_YEAR,-Math.max(0,activityRangeDays-1));return start.getTimeInMillis();}
    private JSONArray activityEventsInRange(){JSONArray all=DataStore.array(this,"events"),filtered=new JSONArray();long from=activityRangeStartMillis();for(int i=0;i<all.length();i++){JSONObject event=all.optJSONObject(i);if(event!=null&&event.optLong("at",0)>=from)filtered.put(event);}return filtered;}
    private String csvCell(String value){String s=value==null?"":value.replace("\r"," ").replace("\n"," ");return "\""+s.replace("\"","\"\"")+"\"";}
    private void csvRow(StringBuilder out,String... cells){for(int i=0;i<cells.length;i++){if(i>0)out.append(',');out.append(csvCell(cells[i]));}out.append("\r\n");}
    private String buildUsageReportCsv(){boolean metrics=DataStore.prefs(this).getBoolean("usage_metrics_enabled",true),history=DataStore.prefs(this).getBoolean("activity_history_enabled",true);StringBuilder out=new StringBuilder();csvRow(out,"TicTic usage report");csvRow(out,"Period",activityRangeCaption());csvRow(out,"Generated",new SimpleDateFormat("yyyy-MM-dd HH:mm:ss z",Locale.getDefault()).format(new Date()));csvRow(out,"Usage metrics",metrics?"Enabled":"Paused in Settings");csvRow(out,"Activity history setting",history?"Enabled":"Paused; existing retained rows may still be included");csvRow(out,"");csvRow(out,"Summary metric","Value");csvRow(out,"App foreground time",metrics?UsageTracker.formatDuration(UsageTracker.usageMillis(this,activityRangeDays)+pendingUsageMs):"Paused");csvRow(out,"Clock screen time",metrics?UsageTracker.formatDuration(UsageTracker.clockMillis(this,activityRangeDays)+pendingClockMs):"Paused");csvRow(out,"Widget refreshes",metrics?String.valueOf(UsageTracker.widgetRefreshes(this,activityRangeDays)):"Paused");csvRow(out,"App events",metrics?String.valueOf(UsageTracker.eventCount(this,activityRangeDays)):"Paused");String[] kinds={"Alarm","Reminder","Timer","Stopwatch","Routine","Clock","Widget","Settings"};for(String kind:kinds)csvRow(out,kind+" events",metrics?String.valueOf(UsageTracker.eventCount(this,activityRangeDays,kind)):"Paused");csvRow(out,"");csvRow(out,"Recent activity in selected window (local history; labels/details may be included)");csvRow(out,"Timestamp","Category","Action","Details");JSONArray events=activityEventsInRange();for(int i=0;i<events.length();i++){JSONObject event=events.optJSONObject(i);if(event==null)continue;long at=event.optLong("at",0);String when=at>0?new SimpleDateFormat("yyyy-MM-dd HH:mm:ss z",Locale.getDefault()).format(new Date(at)):"";csvRow(out,when,event.optString("type",""),event.optString("title",""),event.optString("detail",""));}return out.toString();}
    private void saveUsageReport(){String period=activityRangeDays==1?"today":activityRangeDays==7?"7-days":"30-days";String date=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("text/csv");intent.putExtra(Intent.EXTRA_TITLE,"tictic-usage-"+period+"-"+date+".csv");try{startActivityForResult(intent,87);}catch(Exception e){toast("Could not open the system file picker.");}}
