    private String nextSequenceName(String prefix,JSONArray saved,String field,long editingId){java.util.HashSet<Integer> used=new java.util.HashSet<>();String expected=prefix.toLowerCase(Locale.ROOT)+" ";for(int i=0;i<saved.length();i++){JSONObject item=saved.optJSONObject(i);if(item==null||editingId>0&&item.optLong("id")==editingId)continue;String name=item.optString(field,"").trim().toLowerCase(Locale.ROOT);if(!name.startsWith(expected))continue;String number=name.substring(expected.length()).trim();if(number.matches("0*[0-9]+"))try{used.add(Integer.parseInt(number));}catch(Exception ignored){}}for(int i=1;i<100000;i++)if(!used.contains(i))return prefix+" "+String.format(Locale.ROOT,"%02d",i);return prefix+" "+System.currentTimeMillis();}
